import sys
sys.setrecursionlimit(1000000)
MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    s = [int(next(it)) for _ in range(N)]
    t = [int(next(it)) for _ in range(N)]

    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i, mask):
        if i == N:
            return 1
        # Try leaving cow i unmatched
        can_leave = True
        for j in range(N):
            if not (mask & (1 << j)) and s[i] <= t[j]:
                can_leave = False
                break
        ans = 0
        if can_leave:
            ans = (ans + dfs(i+1, mask)) % MOD
        # Try matching cow i to an available barn
        for j in range(N):
            if not (mask & (1 << j)) and s[i] <= t[j]:
                ans = (ans + dfs(i+1, mask | (1 << j))) % MOD
        return ans

    result = dfs(0, 0)
    print(result)

if __name__ == "__main__":
    solve()
